$rterm = "C:\Program Files\R\R-4.6.1\bin\x64\Rterm.exe"
$script:queue = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()
$psi = New-Object System.Diagnostics.ProcessStartInfo
$psi.FileName = $rterm
$psi.Arguments = "--vanilla --quiet --no-save --no-restore"
$psi.UseShellExecute = $false
$psi.RedirectStandardInput = $true
$psi.RedirectStandardOutput = $true
$psi.RedirectStandardError = $true
$psi.CreateNoWindow = $true
$p = [Diagnostics.Process]::Start($psi)
$p.add_OutputDataReceived({
  param($sender, $e)
  if ($null -ne $e.Data) { $script:queue.Enqueue($e.Data) }
})
$p.add_ErrorDataReceived({
  param($sender, $e)
  if ($null -ne $e.Data) { $script:queue.Enqueue($e.Data) }
})
$p.BeginOutputReadLine()
$p.BeginErrorReadLine()
$listener = [System.Net.Sockets.TcpListener]::new([System.Net.IPAddress]::Loopback, 47821)
$listener.Start()
Write-Output "READY bridge_pid=$PID r_pid=$($p.Id) port=47821"
function Wait-Marker([string]$marker, [int]$timeoutMs) {
  $buf = New-Object System.Collections.Generic.List[string]
  $sw = [Diagnostics.Stopwatch]::StartNew()
  while ($sw.ElapsedMilliseconds -lt $timeoutMs) {
    $line = $null
    while ($script:queue.TryDequeue([ref]$line)) {
      if ($line -eq $marker) { return $buf }
      $buf.Add($line)
    }
    Start-Sleep -Milliseconds 30
  }
  $buf.Add("TIMEOUT")
  return $buf
}
while ($true) {
  $client = $listener.AcceptTcpClient()
  try {
    $stream = $client.GetStream()
    $reader = New-Object System.IO.StreamReader($stream)
    $writer = New-Object System.IO.StreamWriter($stream)
    $writer.AutoFlush = $true
    $cmd = $reader.ReadLine()
    if ($null -eq $cmd) { continue }
    if ($cmd -eq "__SHUTDOWN__") {
      $p.StandardInput.WriteLine("q(save='no')")
      $p.StandardInput.Close()
      if (-not $p.WaitForExit(8000)) {
        $writer.WriteLine("SHUTDOWN_TIMEOUT r_pid=$($p.Id)")
      } else {
        $writer.WriteLine("SHUTDOWN_OK r_pid=$($p.Id) exit=$($p.ExitCode)")
      }
      $writer.WriteLine("__END__")
      break
    }
    $marker = "___MARK_" + [guid]::NewGuid().ToString("N") + "___"
    $p.StandardInput.WriteLine($cmd)
    $p.StandardInput.WriteLine("cat('$marker','`n',sep=''); flush(stdout())")
    $lines = Wait-Marker $marker 20000
    foreach ($line in $lines) { $writer.WriteLine($line) }
    $writer.WriteLine("__END__")
  } finally {
    $client.Close()
  }
}
$listener.Stop()
Write-Output "BRIDGE_EXIT"

$code = @'
using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading;

public class RSessionBridge2 {
  public static void Run(string rterm, int port) {
    try {
      var psi = new ProcessStartInfo();
      psi.FileName = rterm;
      psi.Arguments = "--vanilla --quiet --no-save --no-restore";
      psi.UseShellExecute = false;
      psi.RedirectStandardInput = true;
      psi.RedirectStandardOutput = true;
      psi.RedirectStandardError = true;
      psi.CreateNoWindow = true;
      var p = Process.Start(psi);
      var queue = new ConcurrentQueue<string>();
      var tOut = new Thread(() => ReadLoop(p.StandardOutput, queue));
      var tErr = new Thread(() => ReadLoop(p.StandardError, queue));
      tOut.IsBackground = true;
      tErr.IsBackground = true;
      tOut.Start();
      tErr.Start();
      Console.WriteLine("READY bridge_pid=" + Process.GetCurrentProcess().Id + " r_pid=" + p.Id + " port=" + port);
      Console.Out.Flush();
      var listener = new TcpListener(IPAddress.Loopback, port);
      listener.Start();
      while (true) {
        var client = listener.AcceptTcpClient();
        try {
          using (var stream = client.GetStream())
          using (var reader = new StreamReader(stream, Encoding.UTF8))
          using (var writer = new StreamWriter(stream, new UTF8Encoding(false)) { AutoFlush = true }) {
            var cmd = reader.ReadLine();
            if (cmd == null) continue;
            if (cmd == "__SHUTDOWN__") {
              p.StandardInput.WriteLine("q(save=\"no\")");
              p.StandardInput.Close();
              bool ok = p.WaitForExit(8000);
              writer.WriteLine(ok ? ("SHUTDOWN_OK r_pid=" + p.Id + " exit=" + p.ExitCode) : ("SHUTDOWN_TIMEOUT r_pid=" + p.Id));
              writer.WriteLine("__END__");
              break;
            }
            var marker = "___MARK_" + Guid.NewGuid().ToString("N") + "___";
            p.StandardInput.WriteLine(cmd);
            p.StandardInput.WriteLine("cat(\"" + marker + "\\n\"); flush(stdout())");
            var buf = new StringBuilder();
            var sw = Stopwatch.StartNew();
            bool found = false;
            while (sw.ElapsedMilliseconds < 20000) {
              string line;
              while (queue.TryDequeue(out line)) {
                if (line == marker) { found = true; break; }
                buf.AppendLine(line);
              }
              if (found) break;
              Thread.Sleep(30);
            }
            if (!found) buf.AppendLine("TIMEOUT");
            writer.Write(buf.ToString());
            writer.WriteLine("__END__");
          }
        } finally {
          client.Close();
        }
      }
      listener.Stop();
      Console.WriteLine("BRIDGE_EXIT");
      Console.Out.Flush();
    } catch (Exception ex) {
      Console.WriteLine("BRIDGE_ERROR " + ex.ToString());
      Console.Out.Flush();
    }
  }

  static void ReadLoop(StreamReader r, ConcurrentQueue<string> q) {
    try {
      string line;
      while ((line = r.ReadLine()) != null) q.Enqueue(line);
    } catch (Exception ex) {
      q.Enqueue("READ_ERROR " + ex.Message);
    }
  }
}
